@push('scripts')<script>
document.getElementById('memberSearch')?.addEventListener('input', function () { const query = this.value.toLowerCase(); document.querySelectorAll('#membersTable tbody tr').forEach((row) => row.style.display = row.innerText.toLowerCase().includes(query) ? '' : 'none'); });
document.querySelectorAll('[data-open-member]').forEach((button) => button.addEventListener('click', () => document.getElementById(button.dataset.openMember)?.showModal()));
